@namespace sv_059b63eb66ec45ee8317e33da3aef8d0.Components.Application

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep && !isCompleted;

            <div class="text-center flex-fill" style="z-index: 1;">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepClass(step)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture && !isCompleted)"
                        @onclick="() => OnStepClicked(step)">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : "")">@StepNames[i]</div>
            </div>
        }
    </div>
    <div class="progress mt-2" style="height: 4px;">
        <div class="progress-bar" style="width: @ProgressPercent()%"></div>
    </div>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private string StepClass(int step)
    {
        if (step == CurrentStep) return "btn-primary";
        if (CompletedSteps.Contains(step)) return "btn-success";
        return "btn-outline-secondary";
    }

    private int ProgressPercent() => (int)((CurrentStep - 1) / 4.0 * 100);

    private async Task OnStepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

@namespace sv_059b63eb66ec45ee8317e33da3aef8d0.Components.Application

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h6 class="card-title mb-0">Position @Index</h6>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="() => OnRemove.InvokeAsync()">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Company"
                       @onchange="e => Update(company: e.Value?.ToString())" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title <span class="text-danger">*</span></label>
                <input type="text" class="form-control" value="@Title"
                       @onchange="e => Update(title: e.Value?.ToString())" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date <span class="text-danger">*</span></label>
                <input type="date" class="form-control" value="@StartDate?.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(startDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
            </div>
            <div class="col-md-4">
                <label class="form-label">End Date</label>
                <input type="date" class="form-control" value="@EndDate?.ToString("yyyy-MM-dd")"
                       disabled="@IsCurrent"
                       @onchange="e => Update(endDate: DateTime.TryParse(e.Value?.ToString(), out var d) ? d : null)" />
            </div>
            <div class="col-md-4 d-flex align-items-end">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="current-@Index" checked="@IsCurrent"
                           @onchange="e => OnIsCurrentChanged((bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="current-@Index">I currently work here</label>
                </div>
            </div>
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Description"
                          @onchange="e => Update(description: e.Value?.ToString())"></textarea>
            </div>
        </div>
    </div>
