@namespace sv_059b63eb66ec45ee8317e33da3aef8d0.Components.Application

<nav aria-label="Application steps" class="mb-4">
    <div class="d-flex justify-content-between position-relative">
        @for (int i = 0; i < StepNames.Length; i++)
        {
            var step = i + 1;
            var isCompleted = CompletedSteps.Contains(step);
            var isCurrent = step == CurrentStep;
            var isFuture = step > CurrentStep && !isCompleted;

            <div class="text-center flex-fill" style="z-index: 1;">
                <button class="btn rounded-circle d-inline-flex align-items-center justify-content-center @StepClass(step)"
                        style="width: 40px; height: 40px; font-size: 0.85rem;"
                        disabled="@(isFuture && !isCompleted)"
                        @onclick="() => OnStepClicked(step)">
                    @if (isCompleted && !isCurrent)
                    {
                        <span>&#10003;</span>
                    }
                    else
                    {
                        @step
                    }
                </button>
                <div class="small mt-1 @(isFuture ? "text-muted" : "")">@StepNames[i]</div>
            </div>
        }
    </div>
    <div class="progress mt-2" style="height: 4px;">
        <div class="progress-bar" style="width: @ProgressPercent()%"></div>
    </div>
</nav>

@code {
    private static readonly string[] StepNames = { "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit" };

    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public EventCallback<int> OnStepClicked { get; set; }

    private string StepClass(int step)
    {
        if (step == CurrentStep) return "btn-primary";
        if (CompletedSteps.Contains(step)) return "btn-success";
        return "btn-outline-secondary";
    }

    private int ProgressPercent() => (int)((CurrentStep - 1) / 4.0 * 100);

    private async Task OnStepClicked(int step)
    {
        if (CompletedSteps.Contains(step))
        {
            await OnStepClicked.InvokeAsync(step);
        }
    }
}

