@namespace sv_059b63eb66ec45ee8317e33da3aef8d0.Components.Application

<h4 class="mb-3">Cover Letter</h4>

<div class="mb-3">
    <label class="form-label">Write your cover letter</label>
    <textarea class="form-control" rows="12" maxlength="@MaxLength"
              value="@CoverLetter"
              @oninput="e => { CoverLetter = e.Value?.ToString() ?? ""; OnCoverLetterChanged.InvokeAsync(CoverLetter); }"></textarea>
    <div class="form-text text-end">
        @(CoverLetter?.Length ?? 0) / @MaxLength characters
    </div>
</div>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="d-flex justify-content-between mt-3">
    <button class="btn btn-outline-secondary" @onclick="() => OnBack.InvokeAsync()">&larr; Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next &rarr;</button>
</div>

@code {
    private const int MaxLength = 2000;

    [Parameter] public string CoverLetter { get; set; } = "";
    [Parameter, EditorRequired] public EventCallback<string> OnNext { get; set; }
    [Parameter, EditorRequired] public EventCallback OnBack { get; set; }
    [Parameter] public EventCallback<string> OnCoverLetterChanged { get; set; }

    private string? ErrorMessage;

    private async Task HandleNext()
    {
        ErrorMessage = null;
        if (string.IsNullOrWhiteSpace(CoverLetter))
        {
            ErrorMessage = "Please write a cover letter before proceeding.";
            return;
        }
        await OnNext.InvokeAsync(CoverLetter);
    }
}

